// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {PrivatePool} from "../src/PrivatePool.sol";

contract InvMutTest is Test {
    PrivatePool c;
    function setUp() public { c = new PrivatePool(address(this), address(this), address(this)); }
    function testFuzz_property(address _nft) public {
        vm.assume(_nft != address(0));
        address _baseToken = address(0x1);
        uint128 _virtualBaseTokenReserves = 100;
        uint128 _virtualNftReserves = 100;
        uint56 _changeFee = 0;
        uint16 _feeRate = 0;
        bytes32 _merkleRoot = bytes32(0);
        bool _useStolenNftOracle = false;
        bool _payRoyalties = false;
        c.initialize(_baseToken, _nft, _virtualBaseTokenReserves, _virtualNftReserves, _changeFee, _feeRate, _merkleRoot, _useStolenNftOracle, _payRoyalties);
        assertEq(c.nft(), _nft);
    }
}
